/*
 *  Job‑Shop Scheduling – simple heuristic + hill climbing
 *
 *  1) Build a feasible schedule by a greedy “earliest‑start” rule.
 *     When several operations can start at the same earliest time we
 *     prefer the job with the largest remaining processing work and,
 *     finally, break ties randomly.
 *  2) Keep the best schedule (smallest makespan) found within the time limit.
 *  3) Improve it with a fast local search: repeatedly try to swap two
 *     adjacent jobs on a machine, accept the swap only if the resulting
 *     machine order is still feasible and the makespan decreases.
 *
 *  The schedule is represented only by the order of jobs on each machine.
 *  From a given order we can compute the minimum possible makespan by
 *  simulating the earliest‑feasible start times (longest‑path in the
 *  disjunctive graph).  This simulation runs in O(J·M·M) ≤ 3·10⁴ operations
 *  for the largest instances, so many evaluations fit easily into the 1 s
 *  limit.
 *
 *  The program is deterministic apart from a fixed pseudorandom generator
 *  (seed = 123456789) used for tie‑breaking and for the local‑search moves.
 */

#include <bits/stdc++.h>
using namespace std;

struct Op {
    int machine;       // machine index
    int proc;          // processing time
};

using ll = long long;

/* ------------------------------------------------------------------ */
// compute makespan for a fixed machine order (seq)
// If the order is infeasible (deadlock) LLONG_MAX is returned.
static ll computeMakespan(const vector<vector<int>>& seq,
                          const vector<vector<Op>>& jobOps,
                          int J, int M)
{
    vector<int> nextOp(J, 0);               // next operation index of each job
    vector<ll> jobReady(J, 0);              // completion time of last op of each job
    vector<ll> machAvail(M, 0);             // when each machine becomes free
    vector<int> headPos(M, 0);              // current head position on each machine
    int scheduled = 0;
    const int totalOps = J * M;

    while (scheduled < totalOps) {
        ll bestStart = LLONG_MAX;
        int bestM = -1, bestJ = -1;

        // examine heads of all machines
        for (int m = 0; m < M; ++m) {
            int pos = headPos[m];
            if (pos >= J) continue;                     // this machine finished
            int j = seq[m][pos];
            int opIdx = nextOp[j];
            if (opIdx >= M) continue;                   // job already finished (should not happen)
            if (jobOps[j][opIdx].machine != m) continue; // job not ready for this machine – deadlock candidate

            ll start = max(jobReady[j], machAvail[m]);
            if (start < bestStart) {
                bestStart = start;
                bestM = m;
                bestJ = j;
            }
        }

        if (bestM == -1) return LLONG_MAX; // infeasible (cycle)

        // schedule the chosen operation
        const Op& op = jobOps[bestJ][nextOp[bestJ]];
        ll start = max(jobReady[bestJ], machAvail[bestM]);
        ll finish = start + op.proc;

        jobReady[bestJ] = finish;
        machAvail[bestM] = finish;
        ++nextOp[bestJ];
        ++headPos[bestM];
        ++scheduled;
    }

    ll makespan = 0;
    for (int j = 0; j < J; ++j) makespan = max(makespan, jobReady[j]);
    return makespan;
}

/* ------------------------------------------------------------------ */
// greedy schedule builder (random tie‑breaking)
// Returns the machine order (seq) and its makespan.
static void greedySchedule(const vector<vector<Op>>& jobOps,
                           const vector<vector<ll>>& suffix,
                           mt19937& rng,
                           vector<vector<int>>& outSeq,
                           ll& outMakespan,
                           bool deterministic = false)
{
    int J = jobOps.size();
    int M = jobOps[0].size();

    vector<int> nextOp(J, 0);
    vector<ll> jobReady(J, 0);
    vector<ll> machAvail(M, 0);
    vector<vector<int>> seq(M);
    for (int m = 0; m < M; ++m) seq[m].reserve(J);

    const int total = J * M;
    for (int scheduled = 0; scheduled < total; ++scheduled) {
        ll bestStart = LLONG_MAX;
        ll bestRem   = -1;
        vector<int> cand; cand.reserve(J);

        for (int j = 0; j < J; ++j) {
            if (nextOp[j] >= M) continue;
            const Op& op = jobOps[j][nextOp[j]];
            ll start = max(jobReady[j], machAvail[op.machine]);

            if (start < bestStart) {
                bestStart = start;
                bestRem   = suffix[j][nextOp[j]];
                cand.clear(); cand.push_back(j);
            } else if (start == bestStart) {
                ll rem = suffix[j][nextOp[j]];
                if (rem > bestRem) {
                    bestRem = rem;
                    cand.clear(); cand.push_back(j);
                } else if (rem == bestRem) {
                    cand.push_back(j);
                }
            }
        }

        int idx;
        if (deterministic) {
            idx = cand[0];                     // first candidate
        } else {
            uniform_int_distribution<int> dist(0, (int)cand.size() - 1);
            idx = cand[dist(rng)];
        }

        const Op& op = jobOps[idx][nextOp[idx]];
        ll start = max(jobReady[idx], machAvail[op.machine]);
        ll finish = start + op.proc;

        jobReady[idx] = finish;
        machAvail[op.machine] = finish;
        seq[op.machine].push_back(idx);
        ++nextOp[idx];
    }

    outSeq = move(seq);
    outMakespan = 0;
    for (int j = 0; j < J; ++j) outMakespan = max(outMakespan, jobReady[j]);
}

/* ------------------------------------------------------------------ */
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int J, M;
    if (!(cin >> J >> M)) return 0;

    vector<vector<Op>> jobOps(J, vector<Op>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobOps[j][k] = {m, p};
        }
    }

    // suffix sums: remaining work from position k (inclusive) to end
    vector<vector<ll>> suffix(J, vector<ll>(M + 1, 0));
    for (int j = 0; j < J; ++j) {
        for (int k = M - 1; k >= 0; --k) {
            suffix[j][k] = suffix[j][k + 1] + jobOps[j][k].proc;
        }
    }

    mt19937 rng(123456789);                 // fixed seed → reproducible runs

    const double TIME_LIMIT = 0.95;         // seconds
    auto tStart = chrono::steady_clock::now();

    // --------------------------------------------------------------
    // 1) First deterministic run (no random tie‑breaking)
    vector<vector<int>> bestSeq;
    ll bestMakespan = LLONG_MAX;
    {
        vector<vector<int>> seq;
        ll makespan;
        greedySchedule(jobOps, suffix, rng, seq, makespan, true);
        bestSeq = move(seq);
        bestMakespan = makespan;
    }

    // --------------------------------------------------------------
    // 2) Many random greedy runs while we have time left (≈70% of budget)
    while (true) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - tStart).count();
        if (elapsed >= TIME_LIMIT * 0.7) break;

        vector<vector<int>> seq;
        ll makespan;
        greedySchedule(jobOps, suffix, rng, seq, makespan, false);
        if (makespan < bestMakespan) {
            bestMakespan = makespan;
            bestSeq = move(seq);
        }
    }

    // --------------------------------------------------------------
    // 3) Simple hill‑climbing: adjacent swaps on machines
    vector<vector<int>> curSeq = bestSeq;
    while (true) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - tStart).count();
        if (elapsed >= TIME_LIMIT) break;

        // pick a random machine and a random adjacent pair
        int m = uniform_int_distribution<int>(0, M - 1)(rng);
        int i = uniform_int_distribution<int>(0, J - 2)(rng);

        swap(curSeq[m][i], curSeq[m][i + 1]);
        ll newMakespan = computeMakespan(curSeq, jobOps, J, M);

        if (newMakespan < bestMakespan) {
            // improvement – keep it
            bestMakespan = newMakespan;
            bestSeq = curSeq;
        } else {
            // revert the useless swap
            swap(curSeq[m][i], curSeq[m][i + 1]);
        }
    }

    // --------------------------------------------------------------
    // output the best machine orders
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestSeq[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
 * Job Shop Scheduling – simple constructive heuristic
 *
 * The algorithm builds a feasible schedule directly (no start times are printed).
 * For each job we keep the index of the next unscheduled operation and its ready time.
 * For each machine we keep the time when it becomes free.
 *
 * All jobs' next operations are kept in a priority queue ordered by:
 *   1) earliest possible start time = max(job ready, machine free)
 *   2) larger remaining total processing time of the job (to give priority to long jobs)
 *   3) smaller processing time (SPT as a secondary tie‑breaker)
 *   4) smaller job id
 *
 * The operation on the top of the queue is scheduled at its earliest start time,
 * the machine and the job become busy until the operation finishes,
 * the order of jobs on that machine is recorded.
 * After the operation we update the job's ready time, the machine's free time,
 * decrease the job's remaining work and insert the next operation of the job
 * (if any) into the queue.
 *
 * Because we always respect both precedence (job order) and machine
 * capacity, the produced orderings are always feasible.  The schedule is
 * similar to the classic Giffler‑Thompson list scheduling and gives a
 * reasonably good makespan on the benchmark instances.
 *
 * The program reads one instance and prints for every machine a permutation
 * of all jobs – the order in which that machine processes them.
 */

#include <bits/stdc++.h>
using namespace std;

struct Op {
    int machine;
    long long proc;
};

struct Cand {
    long long est;      // earliest start time (max(job ready, machine free))
    long long proc;     // processing time of this operation
    long long rem;      // total remaining processing time of the job after this op
    int job;            // job index
    int machine;        // machine index
};

struct CandCmp {
    // priority_queue puts on top the element for which cmp returns false for all others.
    // We want a min‑heap on est, then max‑heap on rem, then min on proc, then min on job.
    bool operator()(const Cand& a, const Cand& b) const {
        if (a.est != b.est) return a.est > b.est;          // smaller est first
        if (a.rem != b.rem) return a.rem < b.rem;          // larger remaining work first
        if (a.proc != b.proc) return a.proc > b.proc;      // smaller processing time first
        return a.job > b.job;                              // smaller job id first
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int J, M;
    if (!(cin >> J >> M)) return 0;

    vector<vector<Op>> jobs(J, vector<Op>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobs[j][k] = {m, p};
        }
    }

    // total remaining processing time per job (including all its operations)
    vector<long long> job_rem(J, 0);
    for (int j = 0; j < J; ++j) {
        long long sum = 0;
        for (int k = 0; k < M; ++k) sum += jobs[j][k].proc;
        job_rem[j] = sum;
    }

    vector<int> job_next(J, 0);            // index of the next operation of each job
    vector<long long> job_ready(J, 0);     // time when the next operation of the job can start
    vector<long long> mach_free(M, 0);     // time when each machine becomes free
    vector<vector<int>> mach_order(M);     // resulting permutation per machine

    priority_queue<Cand, vector<Cand>, CandCmp> pq;

    // initialise with the first operation of every job
    for (int j = 0; j < J; ++j) {
        const Op& op = jobs[j][0];
        long long est = max(job_ready[j], mach_free[op.machine]); // = 0
        pq.push({est, op.proc, job_rem[j], j, op.machine});
    }

    long long total_ops = 1LL * J * M;
    long long scheduled = 0;

    while (scheduled < total_ops && !pq.empty()) {
        Cand cur = pq.top(); pq.pop();

        long long real_est = max(job_ready[cur.job], mach_free[cur.machine]);
        if (real_est != cur.est) {
            // outdated entry – recompute and reinsert
            cur.est = real_est;
            pq.push(cur);
            continue;
        }

        // schedule this operation
        long long start = real_est;
        long long finish = start + cur.proc;

        job_ready[cur.job] = finish;
        mach_free[cur.machine] = finish;
        mach_order[cur.machine].push_back(cur.job);
        job_rem[cur.job] -= cur.proc;   // remove the finished part
        ++job_next[cur.job];
        ++scheduled;

        // if the job has more operations, push the next one
        if (job_next[cur.job] < M) {
            const Op& nxt = jobs[cur.job][job_next[cur.job]];
            long long nxt_est = max(job_ready[cur.job], mach_free[nxt.machine]);
            pq.push({nxt_est, nxt.proc, job_rem[cur.job], cur.job, nxt.machine});
        }
    }

    // Output: one line per machine, permutation of all jobs
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < (int)mach_order[m].size(); ++i) {
            if (i) cout << ' ';
            cout << mach_order[m][i];
        }
        // safety: if for any reason the line is shorter, fill with remaining job ids
        // (should never happen with a correct algorithm)
        for (int i = mach_order[m].size(); i < (size_t)J; ++i) {
            if (i) cout << ' ';
            cout << i; // dummy placeholder
        }
        cout << '\n';
    }
    return 0;
}

/*
 * Job‑Shop Scheduling – heuristic solver
 *
 * 1. Build a feasible schedule with an earliest‑start dispatch rule.
 *    While some operations are unscheduled, pick the operation that can
 *    start the earliest (max(job ready time, machine ready time)).
 *    In case of ties we favour the job with larger remaining work.
 *    The order in which jobs are scheduled on each machine gives a
 *    permutation of all jobs for that machine.
 *
 * 2. Compute the makespan of a given set of machine permutations by
 *    longest‑path DP on the disjunctive graph:
 *        – arcs of each job (fixed order)
 *        – arcs induced by the chosen order on each machine
 *    The DP processes the DAG in topological order and yields the
 *    earliest completion time of every operation; the makespan is the
 *    largest completion time.  If the graph contains a cycle the
 *    schedule is infeasible.
 *
 * 3. Improve the solution by local search:
 *    repeatedly try to swap two adjacent jobs on a machine.
 *    Keep a swap only if the new order is feasible and reduces the
 *    makespan.  Continue passes until no improvement or the time limit
 *    (≈0.95 s) is reached.  Finally output the best permutation found.
 *
 * The program runs in well under the 1 s limit for the maximum size
 * (≈1250 operations) and usually yields a makespan far below the
 * reference baseline.
 */

#include <bits/stdc++.h>
using namespace std;

int J, M, N;                                   // number of jobs, machines, operations
vector<vector<int>> jobMach;                  // jobMach[j][k] – k‑th machine of job j
vector<vector<int>> jobProc;                  // jobProc[j][k] – processing time of that operation
vector<vector<int>> posInJob;                 // posInJob[j][m] – position of machine m in job j
vector<vector<int>> opId;                     // opId[j][k] – global id of operation (j,k)
vector<vector<int>> opIdJobMach;              // opIdJobMach[j][m] – id of operation of job j on machine m

vector<long long> jobTotal;                   // total processing time of each job
vector<vector<long long>> jobPref;            // prefix sums of processing times per job

vector<int> proc;                             // processing time per operation (size N)
vector<int> nextJob;                          // next operation in the same job (or -1)
vector<int> baseIndeg;                        // indegree contributed by job arcs only

/* ------------------------------------------------------------------ */
/* DP evaluation of a machine order set --------------------------------*/
vector<int> indeg_;        // indegree during DP
vector<int> succMach;      // successor on the same machine (or -1)
vector<long long> earliest; // earliest start time during DP

bool evaluate(const vector<vector<int>> &order, long long &makespan) {
    // copy job‑only indegrees
    indeg_.assign(N, 0);
    for (int i = 0; i < N; ++i) indeg_[i] = baseIndeg[i];

    succMach.assign(N, -1);

    // add machine arcs
    for (int m = 0; m < M; ++m) {
        const auto &lst = order[m];
        for (int i = 0; i + 1 < (int)lst.size(); ++i) {
            int jPrev = lst[i];
            int jNext = lst[i + 1];
            int opPrev = opIdJobMach[jPrev][m];
            int opNext = opIdJobMach[jNext][m];
            ++indeg_[opNext];
            succMach[opPrev] = opNext;
        }
    }

    // longest‑path DP (topological order)
    earliest.assign(N, 0);
    deque<int> q;
    for (int i = 0; i < N; ++i)
        if (indeg_[i] == 0) q.push_back(i);

    int processed = 0;
    makespan = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        ++processed;
        long long end = earliest[u] + proc[u];
        if (end > makespan) makespan = end;

        // job successor
        int v = nextJob[u];
        if (v != -1) {
            if (earliest[v] < end) earliest[v] = end;
            if (--indeg_[v] == 0) q.push_back(v);
        }
        // machine successor
        v = succMach[u];
        if (v != -1) {
            if (earliest[v] < end) earliest[v] = end;
            if (--indeg_[v] == 0) q.push_back(v);
        }
    }
    // if not all nodes processed → a directed cycle → infeasible
    return processed == N;
}

/* ------------------------------------------------------------------ */
/* Build an initial feasible schedule (earliest‑start rule) -----------*/
vector<vector<int>> build_initial_schedule() {
    vector<long long> machTime(M, 0);      // when each machine becomes free
    vector<long long> jobReady(J, 0);      // completion time of last scheduled op of the job
    vector<int> idx(J, 0);                 // next operation index inside each job
    vector<vector<int>> order(M);          // result: permutation per machine

    int scheduled = 0;
    while (scheduled < N) {
        long long bestStart = LLONG_MAX;
        int bestJob = -1;
        long long bestRemain = -1;         // tie‑breaker: remaining work after this op

        for (int j = 0; j < J; ++j) {
            if (idx[j] >= M) continue;    // all ops of this job already scheduled
            int m = jobMach[j][ idx[j] ];
            long long start = max(jobReady[j], machTime[m]);
            long long remain = jobTotal[j] - jobPref[j][ idx[j] + 1 ]; // work still left after this op
            if (start < bestStart ||
                (start == bestStart && remain > bestRemain)) {
                bestStart = start;
                bestJob = j;
                bestRemain = remain;
            }
        }
        // schedule the chosen operation
        int j = bestJob;
        int m = jobMach[j][ idx[j] ];
        long long p = jobProc[j][ idx[j] ];
        long long finish = bestStart + p;

        machTime[m] = finish;
        jobReady[j] = finish;
        order[m].push_back(j);
        ++idx[j];
        ++scheduled;
    }
    return order;
}

/* ------------------------------------------------------------------ */
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;
    jobMach.assign(J, vector<int>(M));
    jobProc.assign(J, vector<int>(M));
    posInJob.assign(J, vector<int>(M, -1));
    opId.assign(J, vector<int>(M));
    opIdJobMach.assign(J, vector<int>(M));

    // read data
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobMach[j][k] = m;
            jobProc[j][k] = p;
            posInJob[j][m] = k;
        }
    }

    // total work & prefix sums per job
    jobTotal.assign(J, 0);
    jobPref.assign(J, vector<long long>(M + 1, 0));
    for (int j = 0; j < J; ++j) {
        long long sum = 0;
        jobPref[j][0] = 0;
        for (int k = 0; k < M; ++k) {
            sum += jobProc[j][k];
            jobPref[j][k + 1] = sum;
        }
        jobTotal[j] = sum;
    }

    // assign operation ids
    N = J * M;
    proc.assign(N, 0);
    nextJob.assign(N, -1);
    baseIndeg.assign(N, 0);
    int cur = 0;
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            opId[j][k] = cur;
            ++cur;
        }
    }

    // fill global structures
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int oid = opId[j][k];
            proc[oid] = jobProc[j][k];
        }
        for (int k = 0; k < M - 1; ++k) {
            int curOp = opId[j][k];
            int nxtOp = opId[j][k + 1];
            nextJob[curOp] = nxtOp;
            ++baseIndeg[nxtOp];                     // job predecessor
        }
        // map job‑machine → operation id
        for (int m = 0; m < M; ++m) {
            int pos = posInJob[j][m];
            opIdJobMach[j][m] = opId[j][pos];
        }
    }

    // -----------------------------------------------------------------
    // initial solution
    vector<vector<int>> order = build_initial_schedule();

    long long bestMakespan;
    bool feas = evaluate(order, bestMakespan);
    if (!feas) { // should never happen
        cerr << "Initial schedule infeasible!\n";
        return 0;
    }

    // -----------------------------------------------------------------
    // local search (adjacent swaps) – hill climbing
    using Clock = chrono::steady_clock;
    auto startTime = Clock::now();
    const double TIME_LIMIT = 0.94; // seconds
    auto deadline = startTime + chrono::duration<double>(TIME_LIMIT);

    bool anyImprovement = true;
    while (anyImprovement && Clock::now() < deadline) {
        anyImprovement = false;
        for (int m = 0; m < M && Clock::now() < deadline; ++m) {
            for (int i = 0; i + 1 < J && Clock::now() < deadline; ++i) {
                swap(order[m][i], order[m][i + 1]);
                long long newC;
                if (evaluate(order, newC) && newC < bestMakespan) {
                    bestMakespan = newC;
                    anyImprovement = true; // keep the swap
                } else {
                    swap(order[m][i], order[m][i + 1]); // revert
                }
            }
        }
    }

    // -----------------------------------------------------------------
    // final random perturbations (optional, still respecting time limit)
    mt19937 rng(123456789);
    uniform_int_distribution<int> distM(0, M - 1);
    uniform_int_distribution<int> distPos(0, J - 2);

    while (Clock::now() < deadline) {
        int m = distM(rng);
        int i = distPos(rng);
        swap(order[m][i], order[m][i + 1]);
        long long newC;
        if (evaluate(order, newC) && newC < bestMakespan) {
            bestMakespan = newC; // keep improvement
        } else {
            swap(order[m][i], order[m][i + 1]); // revert
        }
    }

    // -----------------------------------------------------------------
    // output result
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << order[m][i];
        }
        cout << '\n';
    }
    return 0;
}
